"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["5135"],{6099(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.ponto_resolucao_anterior_a_dependencia","status":422,"titulo":"O derivado resolve antes de um fato que ele cita"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.ponto_resolucao_anterior_a_dependencia","requisitos":["UNI-REQ-0075","UNI-REQ-0143"],"oQueAconteceu":["O ponto de resolu\xe7\xe3o \xe9 a fase do processo em que o valor do fato fica conhecido. Um fato derivado s\xf3 resolve quando todos os fatos de que depende resolveram (UNI-REQ-0075), ent\xe3o ele n\xe3o pode ser conhecido numa fase anterior \xe0 de uma depend\xeancia: a regra padr\xe3o cita esses fatos, e o resumo de grupo re\xfane as respostas ao fato de membro. A ordem entre as fases vem do cadastro de preced\xeancia entre fases. Fases sem preced\xeancia entre si, e a mesma fase, n\xe3o geram esta recusa. A mensagem cita as duas fases; no cadastro do resumo de grupo, tamb\xe9m cita o c\xf3digo do fato de membro.","A recusa vale para:","- o cadastro do resumo de grupo (`POST /api/configuracao/admin/fatos-candidato/agregados`), contra o fato de membro, com `field` igual a `pontoResolucao`;\\n- a defini\xe7\xe3o das regras padr\xe3o (`PUT /api/configuracao/admin/fatos-candidato/{id}/regras-padrao`), contra cada fato citado, com `field` igual ao \xedndice da regra, como `regras[0]`;\\n- a altera\xe7\xe3o da defini\xe7\xe3o de um derivado ou de um resumo de grupo (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`), contra o que o fato j\xe1 cita ou resume, com `field` igual a `pontoResolucao`.","Na altera\xe7\xe3o, s\xf3 conta a recusa que a mudan\xe7a causa: a que j\xe1 existia antes dela n\xe3o impede a altera\xe7\xe3o. Nada \xe9 gravado."],"comoResolver":["Escolha para o derivado uma fase igual ou posterior \xe0 de todos os fatos de que ele depende, ou tire a cita\xe7\xe3o da regra. Se \xe9 a depend\xeancia que precisa resolver mais cedo, altere a defini\xe7\xe3o dela (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`); a altera\xe7\xe3o s\xf3 \xe9 aceita se o que depende dela continuar valendo."],"ondeAparece":["Cadastro de um fato do cat\xe1logo que resume respostas de grupo","Defini\xe7\xe3o das regras padr\xe3o de um fato derivado por regra","Altera\xe7\xe3o da defini\xe7\xe3o de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);